class TestFindPetsByTags:
    ENDPOINT = f"{BASE_URL}/pet/findByTags"

    @pytest.mark.parametrize(
        "tags,expected_status,expected_schema",
        [
            (["dog", "cat"], 200, "application/json"),  # Valid tags
            (None, 400, None),                         # Missing tags parameter
            (["invalid_tag!"], 400, None),             # Invalid tag format
            ([], 200, "application/json"),             # Edge case: empty tags array
        ],
    )
    def test_find_pets_by_tags_response_codes(
        self, auth_headers, tags, expected_status, expected_schema
    ):
        """
        Verify response status codes and content type.
        """
        params = {"tags": tags} if tags is not None else {}
        response = requests.get(self.ENDPOINT, headers=auth_headers, params=params, timeout=TIMEOUT)
        assert response.status_code == expected_status, f"Expected {expected_status}, got {response.status_code}"

        if expected_schema:
            assert (
                response.headers["Content-Type"] == expected_schema
            ), f"Expected Content-Type {expected_schema}, got {response.headers['Content-Type']}"

    def test_find_pets_by_tags_successful_response(self, auth_headers):
        """
        Test happy path for finding pets by valid tags.
        """
        params = {"tags": ["dog", "cat"]}
        response = requests.get(self.ENDPOINT, headers=auth_headers, params=params, timeout=TIMEOUT)
        assert response.status_code == 200, f"Expected 200, got {response.status_code}"

        json_response = response.json()
        assert isinstance(json_response, list), "Response should be a list of pets"

        for pet in json_response:
            assert "id" in pet, "Pet should have an 'id' field"
            assert "name" in pet, "Pet should have a 'name' field"
            assert "photoUrls" in pet, "Pet should have 'photoUrls' field"
            assert isinstance(pet["photoUrls"], list), "'photoUrls' should be a list"
            assert isinstance(pet["id"], int), "'id' should be an integer"
            assert isinstance(pet["name"], str), "'name' should be a string"

    def test_find_pets_by_tags_missing_auth(self):
        """
        Test finding pets by tags with missing authentication headers.
        """
